MAL=[['拉丁 malus 坏；male 坏地 → 法语 mal、英语 mal-','不良、有害、出错；不一定指道德邪恶']]
MALICE=MAL+[['拉丁 malitia → 古法语 malice → 英语 malice','坏的性质 → 恶意、想伤害人的心思']]
MALICIOUS=MAL+[['拉丁 malitia → malitiosus → 古法语 malicios → 英语 malicious','恶意 → 怀着伤害意图的']]
DISMAL=[['拉丁 dies mali → 古法语 dis mals → 盎格鲁法语 dismal','坏日子、不吉利的日子'],['中古英语 dismal → 英语 dismal','不吉利 → 阴沉的、糟糕得令人沮丧的']]
MALIGN=[['拉丁 male 坏地 + -gnus〔与出生相关〕→ malignus','本性不良、有恶意的']]
MALIGNANT=MALIGN+[['晚期拉丁 malignare → malignans；法语 malignant → 英语 malignant','恶意伤害 → 有害的、恶性的']]
W += [
E('malicious','/məˈlɪʃəs/','恶意的；存心伤害的','不是不小心做错，而是带着让别人受损或难受的意图。','拉丁 malitiosus 来自 malitia 恶意，经古法语进入英语；现代可联系 malice 理解，但历史上已有完整形容词。',MALICIOUS,'malicious gossip 是想伤害名声的闲话；malicious software 是恶意软件。电脑程序没有人的情绪，这里指它被设计出来的有害目的。','malicious intent；malicious gossip；malicious code；a malicious attack。','accidental 是偶然的，malicious 强调恶意；单纯软件有 bug 不自动等于恶意软件。',('Someone spread malicious rumours about her work.','有人恶意散播关于她工作的谣言。'),('The update blocks a known source of malicious code.','这次更新封堵了一个已知的恶意代码来源。'),sources=['https://www.etymonline.com/word/malicious','https://www.oxfordlearnersdictionaries.com/definition/english/malicious']),
E('malware','英 /ˈmælweə/；美 /ˈmælwer/','恶意软件','表面是程序，实际用途是偷偷窃取、破坏、勒索或做其他有害的事。','mal- 坏 + -ware，后者来自 software 等软件词；也常解释为 malicious software 的缩合。',MAL+[['英语 mal- + -ware；联系 malicious software → malware','有害 + 软件 → 恶意软件的总称']],'scan for malware 是扫描恶意软件；malware infection 是设备受恶意软件侵入。通常不可数，不能把每个软件问题都归为 malware。','detect malware；remove malware；malware infection；a malware sample。','virus 是恶意软件中的一种；malware 范围更广，还包括多种窃密、勒索等程序。',('The security tool detected malware in the downloaded file.','安全工具在下载的文件中检测到恶意软件。'),('A software bug is not necessarily a sign of malware.','软件故障不一定意味着存在恶意软件。'),sources=['https://www.etymonline.com/word/malware','https://en.wiktionary.org/wiki/malware#English','https://www.oxfordlearnersdictionaries.com/definition/english/malware']),
E('malice','/ˈmælɪs/','恶意；害人之心','心里希望别人吃亏、受伤或难堪。','拉丁 malitia 坏的性质，来自 malus 坏，经古法语 malice 进入英语。',MALICE,'without malice 是没有恶意；bear someone malice 是对某人怀有恶意。词本身说意图，不说明实际伤害是否已经发生。','without malice；out of malice；bear someone malice。','anger 是愤怒，不必然想伤害；malice 更直接指害人之心。法律里的具体标准需看制度，不能用日常释义替代。',('He spoke carelessly, but without malice.','他说话欠考虑，但并无恶意。'),('She refused to believe that the mistake had been made out of malice.','她不愿相信那个错误是出于恶意造成的。'),sources=['https://www.etymonline.com/word/malice','https://en.wiktionary.org/wiki/malice#English']),
E('dismal','/ˈdɪzməl/','阴沉的；令人沮丧的；糟糕的','像连着坏天气、坏消息，怎么看都提不起精神。','来自古法语 dis mals 坏日子，接拉丁 dies mali；dis- 在这里不是现代否定前缀，不能拆成不坏。',DISMAL,'dismal weather 是阴沉糟糕的天气；a dismal performance 是令人失望的糟糕表现。常带说话人的强烈不满。','dismal weather；a dismal failure；dismal results；a dismal outlook。','dark 可只是光线暗；dismal 还带冷清、沮丧或糟糕的感受。',('We arrived on a dismal afternoon of rain and fog.','我们在一个下雨起雾、阴沉沉的下午抵达。'),('The team’s dismal results led to a change of coach.','球队糟糕的成绩促使俱乐部更换教练。'),sources=['https://www.etymonline.com/word/dismal','https://en.wiktionary.org/wiki/dismal#English']),
E('maliciously','/məˈlɪʃəsli/','恶意地；存心害人地','做这件事时，带着让别人受损或难堪的心思。','malicious + -ly；中古英语已有对应副词形式 maliciousli。',MAL+[['拉丁 malitiosus → 古法语 malicios → 中古英语 malicious → maliciousli → 英语 maliciously','恶意的 → 带恶意地行动']],'maliciously damage property 是恶意毁坏财物；maliciously spread rumours 是存心散播谣言。强调故意和恶意，不只说后果不好。','maliciously damage；maliciously spread；act maliciously。','deliberately 是有意地，目的未必坏；maliciously 明确带伤害意图。',('The files had been maliciously altered.','这些文件遭到了恶意篡改。'),('She was accused of maliciously spreading false information.','她被指控恶意散播虚假信息。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/maliciously','https://en.wiktionary.org/wiki/maliciously#English']),
E('maliciousness','构词参考 /məˈlɪʃəsnəs/','恶意；恶毒的性质','把某句话、举动或态度中想伤害人的那一面单独指出来。','中古英语 maliciousnes 延续下来，现代对应 malicious + -ness。',MAL+[['拉丁 malitiosus → 古法语 malicios → 中古英语 malicious → maliciousnes → 英语 maliciousness','恶意的 → 恶意这种性质']],'the maliciousness of a remark 指一句话的恶毒；不是评论内容尖锐就一定有 maliciousness，还要看其中的伤害意图。','the maliciousness of；sheer maliciousness；a hint of maliciousness。','malice 更简短常见；maliciousness 常把注意力放在某个行为显露出的恶毒性质，两者意义可接近。',('The maliciousness of the comments shocked her colleagues.','那些评论的恶毒让她的同事震惊。'),('He mistook awkwardness for maliciousness.','他把笨拙的表达误当成了恶意。'),sources=['https://www.collinsdictionary.com/dictionary/english/maliciousness','https://en.wiktionary.org/wiki/maliciousness#English']),
E('malaise','/məˈleɪz/','不适感；萎靡；普遍不振的状态','说不出一个明确问题，却觉得身体、心情或整个局面都不太对劲。','借法语 malaise：mal 不好 + aise 舒适、自在；字面是不舒服、不自在。',MAL+[['法语 mal + aise → malaise → 英语 malaise','不舒适 → 身体不适；引申为社会、经济的不振']],'a general feeling of malaise 是全身或整体的不适；economic malaise 是经济长期疲弱的状态。通常不可数，也不是一个具体病名。','a feeling of malaise；economic malaise；a sense of malaise。','illness 可指疾病；malaise 强调泛泛的不舒服。crisis 是危机，malaise 常是持续、弥漫的不振。',('She described a general malaise rather than a sharp pain.','她描述的是全身不舒服，而不是某处剧痛。'),('The article explores the causes of the country’s economic malaise.','文章探讨该国经济不振的原因。'),sources=['https://www.etymonline.com/word/malaise','https://www.oxfordlearnersdictionaries.com/definition/english/malaise']),
E('malignant','/məˈlɪɡnənt/','恶性的；有严重危害的；恶毒的','医学里说会侵袭、可能扩散的癌性病变；一般文字里也能说有害、恶毒的影响。','接晚期拉丁 malignans，即 malignare 恶意伤害的现在分词，经法语或直接借入；不是现代 malign 简单加 -ant。',MALIGNANT,'a malignant tumour 是恶性肿瘤。这个形容词不等于已经发生远处转移，也不能单靠词源判断疾病；文学里的 malignant influence 则说恶劣影响。','a malignant tumour；malignant cells；a malignant influence。','benign 与恶性相对时指良性；malign 也可作形容词说有害，但常用动词义是诋毁。',('The report identified the tumour as malignant.','报告确认该肿瘤为恶性。'),('The novel portrays the adviser as a malignant influence on the ruler.','小说把顾问描写为对统治者产生恶劣影响的人。'),sources=['https://www.etymonline.com/word/malignant','https://en.wiktionary.org/wiki/malignant#English','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/malignant']),
E('malignancy','/məˈlɪɡnənsi/','恶性；恶性肿瘤、癌症；恶毒','把恶性这一性质，或一个具体的恶性病变，作为名词来说。','常分析为 malignant 对应 -cy 名词；也有拉丁 malignantia 借入或影响的分析，不把一种说法写成唯一历史。',MALIGN+[['晚期拉丁 malignans / malignantia；英语 malignant → malignancy','恶性的性质；英语构词和拉丁对应形式都被词源资料提及']],'evidence of malignancy 是恶性证据；a malignancy 可指一个恶性肿瘤或癌症。医学里比日常的坏严谨得多，不能与肿块直接画等号。','evidence of malignancy；a suspected malignancy；the risk of malignancy。','tumour 是肿瘤，不自动意味着恶性；malignancy 明确涉及恶性，是否成立要靠医学判断。',('The biopsy showed no evidence of malignancy.','活检未发现恶性证据。'),('The lecture compared several types of malignancy.','讲座比较了几种恶性肿瘤。'),sources=['https://www.etymonline.com/word/malignancy','https://en.wiktionary.org/wiki/malignancy#English','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/malignant']),
E('malign','/məˈlaɪn/','诋毁；恶意中伤；有害的','作动词是把别人说得很坏，损害其名声；作形容词则说恶意或有害。','形容词经古法语 maligne 接拉丁 malignus；动词另经法语 malignier 或晚期拉丁 malignare 借入，不能只画成英语形容词后转动词。',MALIGN+[['形容词线：拉丁 malignus → 古法语 maligne → 英语 malign','本性不良 → 有害的、恶意的'],['并列动词线：晚期拉丁 malignare；古法语 malignier → 英语 malign','恶意行事、欺骗 → 诋毁他人']],'malign someone’s motives 是把别人的动机说得恶劣；a malign influence 是有害影响。常见 much-maligned 表示经常被贬低、备受非议。','malign somebody；malign someone’s motives；a malign influence。','criticize 可有事实依据且不怀恶意；malign 带恶意中伤的判断。malignant 的 g 发音，malign 的 g 不发音。',('The review unfairly maligned the work of the volunteers.','那篇评论不公正地诋毁了志愿者的工作。'),('The article describes corruption as a malign influence on public life.','文章把腐败描述为对公共生活的有害影响。'),sources=['https://www.etymonline.com/word/malign','https://www.oxfordlearnersdictionaries.com/definition/english/malign_1']),
E('malfeasance','/ˌmælˈfiːzəns/','渎职；职务中的违法不当行为','掌握某项权力或责任，却做了本来不该做的坏事。','借法语 malfaisance，来自 malfaisant 做坏事的；mal- 坏 + faisant，后者来自 faire 做，接拉丁 facere。',MAL+[['法语 mal + faisant → malfaisance → 英语 malfeasance','做坏事 → 尤指履职中的违法或不当行为']],'official malfeasance 是公职人员的不当行为；allegations of malfeasance 是相关指控。常见于严肃新闻和法律文字，不宜拿来泛指工作效率低。','official malfeasance；allegations of malfeasance；investigate malfeasance。','negligence 侧重疏忽，malfeasance 侧重不应做的违法或不当行为；具体法律分类因制度而异。',('The audit uncovered evidence of financial malfeasance.','审计发现了财务违法不当行为的证据。'),('The committee investigated allegations of official malfeasance.','委员会调查了有关公职人员渎职的指控。'),sources=['https://www.etymonline.com/word/malfeasance','https://en.wiktionary.org/wiki/malfeasance#English']),
E('malady','/ˈmælədi/','疾病；弊病；长期困扰的问题','原本是身体不健康，借来形容制度或社会里反复发作的问题。','古法语 maladie 疾病，来自 malade 病着的，接拉丁 male habitus 状况不佳；male 坏地 + habitus 所处状态。',MAL+[['拉丁 male habitus → 古法语 malade → maladie → 英语 malady','状态不佳 → 疾病 → 社会或制度的弊病']],'a mysterious malady 是难以解释的疾病；a social malady 是社会弊病。比 illness 更书面，也常见于历史或文学。','suffer from a malady；a chronic malady；social maladies。','disease 是常用疾病名词；malady 更有书面语感，且容易用于比喻。不是 male 男性 + 一个词尾。',('The diary describes a strange malady that affected the village.','日记描述了一种波及村庄的怪病。'),('The essay treats corruption as a persistent social malady.','文章把腐败看作一种顽固的社会弊病。'),sources=['https://www.etymonline.com/word/malady','https://en.wiktionary.org/wiki/malady#English']),
E('malformed','英 /ˌmælˈfɔːmd/；美 /ˌmælˈfɔːrmd/','形态异常的；格式不正确的','本该按某种结构长成或组织起来，结果形状、组成出了问题。','mal- 不良、出错 + formed 已形成的；现代英语复合形容词。',MAL+[['英语 mal- + formed → malformed','形成得不正常 → 形态或格式有问题的']],'a malformed request 在程序中常指结构不符合要求的请求；malformed fruit 是形状异常的果实。不要把形态描述随意当作对人的评价。','malformed data；a malformed request；a malformed structure。','invalid 范围更大，可以是值不被接受；malformed 特别指出结构或格式不对。',('The server rejected the malformed request.','服务器拒绝了格式不正确的请求。'),('Several malformed fruits were removed during sorting.','分拣时去掉了几个形状异常的果实。'),sources=['https://en.wiktionary.org/wiki/malformed#English','https://www.oxfordlearnersdictionaries.com/definition/english/malformed']),
E('maladaptive','/ˌmæləˈdæptɪv/','不利于适应的；应对失当的','本想靠一种做法应付环境，结果长远看反而更难应付。','mal- 不良 + adaptive 有助于适应的；重点是适应效果不好，不是道德上坏。',MAL+[['英语 mal- + adaptive → maladaptive','适应不良 → 不能有效应对环境的']],'maladaptive coping 指长期效果不好的应对方式；在生物学中也可说某特征在特定环境下不利于生存繁殖。效果取决于环境，不是永远不变。','maladaptive behaviour；maladaptive coping；a maladaptive response。','unusual 只是少见；maladaptive 要看行为或特征是否妨碍适应，不能把不同寻常都称为有问题。',('Avoiding every difficult conversation can become a maladaptive habit.','回避所有困难的谈话，可能变成不利于解决问题的习惯。'),('A trait that was useful in one habitat may be maladaptive in another.','在一种栖息地有用的特征，在另一种环境中可能反而不利。'),sources=['https://en.wiktionary.org/wiki/maladaptive#English','https://www.merriam-webster.com/dictionary/maladaptive']),
E('maladjusted','/ˌmæləˈdʒʌstɪd/','适应不良的；情绪和行为难以适应环境的','形容人难以适应周围的生活和关系，并由此出现明显困扰。','mal- 不良 + adjusted 已适应的；现代英语构词。',MAL+[['英语 mal- + adjusted → maladjusted','未适应好 → 情绪、行为与环境难以协调的']],'旧教育或心理学文字里可见 maladjusted children。这是较笼统、容易贴标签的说法；现代叙述往往更具体地说人在什么方面遇到困难。','socially maladjusted；described as maladjusted；a maladjusted character。','shy 是害羞，introverted 是内向；两者都不能直接等同 maladjusted。',('The old report described the children as maladjusted without explaining their needs.','旧报告把这些孩子称为适应不良，却没有说明他们的具体需要。'),('The novel follows a maladjusted teenager struggling to find a place in a new town.','小说讲述一个适应困难的少年努力在新城镇找到归属的故事。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/maladjusted','https://en.wiktionary.org/wiki/maladjusted#English']),
E('dismally','/ˈdɪzməli/','糟糕地；令人沮丧地；阴沉地','结果差得让人泄气，或说话、环境透着一股灰暗劲。','dismal + -ly；dismal 的历史是坏日子，不是 dis- 加 mal 的现代组合。',DISMAL+[['英语 dismal + -ly → dismally','令人沮丧的 → 糟糕地、沮丧地']],'fail dismally 是惨败、完全没做好；dismally low figures 是低得令人失望的数据。可修饰动作，也可加强形容词。','fail dismally；perform dismally；dismally low；look dismally at。','sadly 可以只是带悲伤；dismally 更突出灰暗、没希望或结果很糟。',('The plan failed dismally during its first trial.','计划在首次试行时败得一塌糊涂。'),('Attendance remained dismally low throughout the week.','整周的到场人数都少得令人失望。'),sources=['https://en.wiktionary.org/wiki/dismally#English','https://www.oxfordlearnersdictionaries.com/definition/english/dismally']),
E('malodorous','英 /ˌmælˈəʊdərəs/；美 /ˌmælˈoʊdərəs/','恶臭的；气味难闻的','不是单纯闻得到，而是气味让人想躲开。','mal- 不好 + odorous 有气味的；odor 气味接拉丁 odor。',MAL+[['英语 mal- + odorous → malodorous','气味不好 → 难闻、恶臭的']],'malodorous waste 是气味难闻的废物；a malodorous drain 是发臭的排水沟。较书面，日常常说 smelly 或 foul-smelling。','malodorous waste；malodorous fumes；a malodorous drain。','odorous 只说有气味，malodorous 明确难闻；odorless 是没有气味。',('A malodorous liquid leaked from the damaged container.','破损容器里漏出一种恶臭液体。'),('The crew cleared the malodorous waste from the alley.','工作人员清走了小巷里发臭的废弃物。'),sources=['https://www.etymonline.com/word/malodorous','https://en.wiktionary.org/wiki/malodorous#English']),
]
