DEFERRED={'amboceptor':'免疫学旧专门术语，暂略。','ancipital':'两刃等较冷门形态词，当前页暂略；既有 capit 精讲保留。','ambilateral':'较冷门双侧形容词，优先 bilateral。','ambilaterality':'较冷门派生名词，暂略。','bilaterality':'较专门两侧性质名词，优先 bilateral。','inequilateral':'较少用不等边形容词，基础学习先掌握 equilateral。','laterality':'较专门侧性概念，暂略。','matrilateral':'亲属制度专门术语，暂略。','nonlateral':'较少用否定形容词，暂略。','plurilateral':'较专门贸易协定用词，本轮先掌握 bilateral、multilateral。','septilateral':'七边的罕用形容词，暂略。','patrilateral':'亲属制度专门术语，当前页暂略。','extralateral':'较少用法律、地质用词，暂略。','semilatus':'专门几何词，暂略。','humic':'专门腐殖酸相关形容词，先掌握 humus。','inhumation':'较少用埋葬名词，优先 burial，暂略。','humate':'专门化学名词，暂略。','disinhume':'较少用掘出动词，优先 exhume。','humation':'罕用埋葬名词，暂略。','humicolous':'专门生物生态形容词，暂略。','inhume':'较少用埋葬动词，优先 bury。','premalignant':'较专门医学阶段形容词，本轮先掌握 malignant。','grand mal':'多词医学旧名称，本轮不另列。','malabsorption':'专门医学吸收不良术语，当前页暂略。'}
VIGIL_ROOT=dict(id='C1636',meaning='醒着、守望；警觉与监视',core='别人可能已经睡下或松懈，你仍醒着留意周围。陪伴病人、监考和监控，都从不同角度接上守望。',image='拉丁 vigil 清醒 → vigilare 守望；vigilia → vigil；vigilans → vigilant；经法语 veiller → surveillance；经西班牙语 vigilante → 私自执法者。',intro='同样是留意，词的实际用途很不一样。vigil 可温柔地陪护，也可集体悼念；surveillance 是有目的的监视；vigilante 在英语里已特指自行执法的人。不能只记一个警惕就混着使用。',forms='vigilant 的结尾读 /lənt/，vigilante 结尾读 /lænti/。reveille 的英美读音差别明显。英语 surveil 通常从较早的 surveillance 逆构，历史方向要与现代动词、名词搭配分开。',branches=[['警觉与保持注意','vigilant, vigilance, vigilantly'],['守候与唤醒','vigil, reveille'],['监控','surveillance, surveil'],['考场监督','invigilate, invigilator'],['私人接管执法','vigilante, vigilantism']],contrasts='vigilant 是警觉，vigilante 是私自执法者。invigilate 是监考，grade 是评分。vigil 不必整夜举行，surveillance 也不一定都是秘密跟踪。',practice='用 vigilant 描写救生员，用 vigil 描写陪护；解释 vigilant 与 vigilante 为何不能互换；比较监考与批改试卷。',words=list(ASSIGN['roots'][105]['family']),exclude={})
AMBI_ROOT=dict(id='C0043',meaning='周围；两边、两方面',core='可以想成绕着一个点走，也可以想成两边都照顾到。环绕着形成环境，两边都能用则形成双手灵巧。',image='ambi- 周围、两边 + ire 去 → ambire 绕行 → ambit、ambition、ambient；ambi- + dexter 右手 → ambidextrous。',intro='ambition 的历史画面是四处争取支持；ambient 是环绕四周的，ambience 是场所给人的整体气氛。另一支 ambiguous、ambivalent 都与两方面有关，却分别表示意思不清和内心有相反感受。andante 的意大利语来源明确，更远与 ambire 的联系有争议，作为传统关联阅读。',forms='ambi- 在历史构词中可见 amb-、am-、an- 等形式，但不能看到这些字母就直接认根。ambition 不是现代 ambit 加 -ion 才造出；ambitious、ambidexterity 也有各自的历史路线。',branches=[['围绕的环境与边界','ambient, ambience, ambiance, ambit'],['争取成就','ambition, ambitious, ambitiously'],['两手都灵巧','ambidextrous, ambidexterity'],['两种解释、两种心情','ambiguous, ambiguity, ambiguously, unambiguous, ambivalent, ambivalence'],['绕切的历史旁支','amputation'],['来源有争议的传统关联','andante']],contrasts='ambiguous 是信息不清楚，ambivalent 是心里同时有相反感受；ambience 与 ambiance 通常是同词不同拼写。ambition 可褒可贬，不能一律译为有恶意的野心。',practice='比较 an ambitious plan 与 an ambiguous plan；用 ambient temperature 和 ambience 各说一句话；用 ambidextrous 描写一种左右手都适用的物品。',words=[w for w in ASSIGN['roots'][106]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][106]['family'] if w in DEFERRED})
LATER_ROOT=dict(id='C0652',meaning='侧面；边；参与的一方',core='看一个物体有哪些边，再把每一边想成参与的一方。双边谈判就是两方坐下来谈，侧向移动则是往旁边移。',image='拉丁 latus / lateris 侧面 → lateralis → lateral；bi-、tri-、multi- 与 lateral 结合，分别表示两方、三方、多方。',intro='这一组同时活在几何、身体方位、工作和外交语言里。quadrilateral 是四边形，lateral move 可以是工作平调，collateral 的金融义则从附带保障发展。形状与参与方共享侧面的画面，具体意思由语境决定。',forms='later- 的来源是 latus 的属格词干 lateris，不是 late 的比较级 later。collateral 接中古拉丁 collateralis；equilateral 接晚期拉丁 aequilateralis，不能全当成现代英语现拼。',branches=[['侧向与旁边','lateral, laterally, collateral'],['两方、单方与多方','bilateral, bilaterally, bilateralism, unilateral, unilaterally, unilateralism, multilateral, multilateralism, trilateral'],['几何的边','quadrilateral, equilateral'],['身体参照','ipsilateral, contralateral']],contrasts='ipsilateral 同侧，contralateral 对侧，bilateral 双侧。equilateral 保证各边相等，一般多边形不因此自动等角。collateral 作名词可以是抵押担保财产。',practice='用 lateral move 描写平调；比较 unilateral、bilateral、trilateral；说明为什么菱形等边却不一定是正方形。',words=[w for w in ASSIGN['roots'][107]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][107]['family'])+ASSIGN['roots'][107]['unmatched'] if w in DEFERRED})
HUM_ROOT=dict(id='C0573',meaning='地面、土；低处与谦卑',core='地面在低处，于是低的画面可以转成地位低、姿态谦逊；被人压低，则可能变成受辱。另一路是真正埋进土中、再取出来。',image='拉丁 humus 土 → humilis 低微的 → humble、humility；humiliare 使低下 → humiliation、humiliate；humare 埋葬 → exhumare → exhume。',intro='这组最容易误会的是谦逊与羞辱。humble 可以是一种受到尊重的态度；humiliated 通常是尊严受伤；humbling 经历则可能让人感到敬畏、收起骄傲。humus 和 exhume 保留了土这一具体来源。',forms='humble 的开头通常 /hʌm/，humility、humiliate 则 /hjuːm/。humiliation 在英语中早于 humiliate；后者有名词逆构与拉丁分词借入两说。exhumation 也有拉丁名词经法语借入的路线。',branches=[['谦逊与认清局限','humble, humility, humbly, humbling'],['使人受辱与受辱感','humiliate, humiliation, humiliated, humiliating, humiliatingly'],['土壤与埋葬','humus, exhume, exhumation']],contrasts='humility 是谦逊品质，humiliation 是羞辱。humbling 可正面，humiliating 通常负面。humus 腐殖质与 hummus 鹰嘴豆泥不同源。',practice='用 humiliated 描写人的感受、humiliating 描写事情；举一个正面的 humbling experience；比较 exhume 与 excavate。',words=[w for w in ASSIGN['roots'][108]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][108]['family'] if w in DEFERRED})
MAL_ROOT=dict(id='C0701',meaning='不良、坏、出错；恶意与失常',core='有时是人存心使坏，有时只是设备、形态或适应出了问题。先判断坏的是意图还是运作，不要把所有 mal- 都翻成道德邪恶。',image='拉丁 malus 坏、male 坏地 → 法语 mal、英语 mal-；malitia → malice；malignus → malign；mal + aise → malaise；dies mali 坏日子 → dismal。',intro='malicious 指有意伤害，malformed 指结构不合要求，malnutrition 指营养不足或失衡，这些不是同一种坏。dismal 从坏日子发展成阴沉糟糕，不能把 dis- 当否定前缀硬拆。malady 则经 male habitus 状况不佳而来。',forms='malice 的开头读 /mæl/，malicious 常读 /mə/。malign 中 g 不发音，malignant 中 g 发音。malware 是近代软件词，不是拉丁语本来就有的整词。',branches=[['恶意与诋毁','malice, malicious, maliciously, maliciousness, malign, malevolent'],['程序、工作与结构异常','malware, malfunction, malfunctioning, malpractice, malfeasance, maladministration, malformation, malformed'],['状态不佳与气味','malaise, malady, dismal, dismally, malodorous'],['营养、疾病与适应','malnutrition, malnourished, malnourishment, malignant, malignancy, maladaptive, maladjusted'],['其他已讲词','malediction, malefaction']],contrasts='deliberately 只说故意，maliciously 明确有恶意。malign 是诋毁或有害的，malignant 常说医学恶性。malformed 不等于 malicious；一个格式错误的文件未必包含恶意代码。',practice='比较一个有 bug 的程序与 malware；用 dismal 形容天气、用 dismally 描写表现；说明 malign 与 malignant 不宜互换。',words=list(dict.fromkeys([w for w in ASSIGN['roots'][109]['family'] if w not in DEFERRED]+['malfunctioning'])),exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][109]['family'])+ASSIGN['roots'][109]['words'] if w in DEFERRED})
roots=[VIGIL_ROOT,AMBI_ROOT,LATER_ROOT,HUM_ROOT,MAL_ROOT]
ALREADY={'maladministration'}
expected={w for r in ASSIGN['roots'][105:110] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED and w not in ALREADY}
